package main
import "github.com/corentings/chess/v2"
var qDiagnosticStats=map[string]uint64{}
type pickerOpportunity struct{hint uint16;killers [2]uint16;quiet,all int}
func recordPickerGeneration(w *searcher,p *chess.Position,moves []chess.Move,e tableEntry,hit bool,ply int)pickerOpportunity{r:=pickerOpportunity{all:len(moves)};if hit{r.hint=e.move}else{r.hint=w.table.boardHint(p)};if w.killers!=nil&&ply>=0&&ply<len(w.killers){r.killers=w.killers[ply]};for i:=range moves{if isQuietMove(moves[i]){r.quiet++}};qDiagnosticStats["main_generations"]++;qDiagnosticStats["full_move_records"]+=uint64(r.all);qDiagnosticStats["quiet_move_records"]+=uint64(r.quiet);return r}
func recordPickerCutoff(r pickerOpportunity,index int,m chess.Move){qDiagnosticStats["main_cutoffs"]++;sig:=encodeMove(m);tableFirst:=index==0&&r.hint!=0&&sig==r.hint;tactical:=!isQuietMove(m);killer:=isQuietMove(m)&&((r.killers[0]!=0&&sig==r.killers[0])||(r.killers[1]!=0&&sig==r.killers[1]));if tableFirst{qDiagnosticStats["table_first_cutoffs"]++;qDiagnosticStats["all_records_avoidable_by_table_first"]+=uint64(r.all)};if tableFirst||tactical||killer{qDiagnosticStats["early_stage_cutoffs"]++;qDiagnosticStats["potential_avoided_quiet_records"]+=uint64(r.quiet)}}

